{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In mice, vistusertib (ON01910.Na), a methoxy-substituted aromatic compound with ionizable amine and carboxylic acid groups, showed brain distribution below 5% of plasma, indicating poor BBB penetration; the query shares methoxyphenyl and ionizable acid/amine motifs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In rats, the polar phosphate-containing compound DHPP-2-14C showed extremely low brain uptake after oral administration; the query contains a similarly ionized phosphinic acid group, supporting poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Merck-3, an amino-alcohol-containing compound, was undetectable in mouse brain after i.v. dosing and was identified as a P-gp substrate; the query's hydroxyethylamine/tertiary amine and polar acidic groups are consistent with efflux-limited brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "SMB-1 had low membrane permeability and poor CNS distribution in rats, with brain concentrations around 0.5 µM after 20 mg/kg subcutaneous dosing; this supports a fail prediction for a polar, ionizable small molecule like the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "14C-MBDA, a phenethylamine amide with polar catechol groups, showed only 0.06% ID/g rat brain uptake; the query contains a phenethylamine-like amino alcohol and carboxylic acid, supporting poor brain uptake.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, multiply ionizable phosphinic-acid/amino-alcohol/carboxylic-acid molecule; all transferable experimental evidence shows poor BBB penetration for structurally related polar/ionizable compounds, so it is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or Kp,uu measurement for the query",
    "No P-gp/Bcrp efflux assay for the query",
    "No human PET, CSF, or clinical CNS exposure data",
    "Exact compound identity and established CNS behavior are unknown"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

